select * from jsonb_populate_recordset(null::bridging.questions, $seed$[{"id":"019f9e72-b6b2-762e-982d-9a230904d542","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"Write x^2 - 10x + 7 in the form (x - a)^2 + b.","model_answer":"(x - 5)^2 - 18","explanation":"Complete the square: x^2 - 10x + 7 = (x^2 - 10x + 25) - 25 + 7 = (x - 5)^2 - 18.","difficulty":"Easy","diagram_path":null,"metadata":{"tags":"algebra,quadratics,completing-the-square","subtopic":"completing the square","question_type":"open-ended","diagram_required":false},"question_type":"open-ended","created_at":"2026-07-26T12:42:25.842Z","updated_at":"2026-07-26T12:42:25.842Z"},{"id":"019f9e72-b681-7ab4-b97f-c92fe8c20252","topic_id":"019f9df7-a2a2-77cc-bb88-40ce254805a8","prompt":"A shirt costs £14.75 in one country. In another country, the same shirt costs $21.99. If the exchange rate is $1 = £0.73, calculate how much more the second price is than the first, in pounds.","model_answer":"£1.30","explanation":"Convert $21.99 to pounds: 21.99 × 0.73 = 16.0527. Subtract 14.75: 16.0527 - 14.75 = 1.3027. To the nearest penny, the difference is £1.30.","difficulty":"Easy","diagram_path":null,"metadata":{"tags":"ratio,exchange-rates,money","subtopic":"exchange rates","question_type":"open-ended","diagram_required":false},"question_type":"open-ended","created_at":"2026-07-26T12:42:25.793Z","updated_at":"2026-07-26T12:42:25.793Z"},{"id":"019f9e72-b688-7ff9-971b-1d6c0e1ef6df","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"Simplify 6a^5b^2 ÷ 3a^2b.","model_answer":"2a^3b","explanation":"Divide coefficients: 6 ÷ 3 = 2. Subtract the powers: a^(5-2) = a^3 and b^(2-1) = b. So the simplified form is 2a^3b.","difficulty":"Easy","diagram_path":null,"metadata":{"tags":"algebra,indices,simplification","subtopic":"indices","question_type":"open-ended","diagram_required":false},"question_type":"open-ended","created_at":"2026-07-26T12:42:25.800Z","updated_at":"2026-07-26T12:42:25.800Z"},{"id":"019f9e72-b68b-7f17-b8a8-f777ff35747f","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"Use the laws of indices to find the value of k if 2^k × 2^4 = 64.","model_answer":"2","explanation":"Combine the powers: 2^(k+4) = 64. Since 64 = 2^6, we get k + 4 = 6. Therefore k = 2.","difficulty":"Easy","diagram_path":null,"metadata":{"tags":"algebra,indices,laws-of-indices","subtopic":"indices","question_type":"open-ended","diagram_required":false},"question_type":"open-ended","created_at":"2026-07-26T12:42:25.803Z","updated_at":"2026-07-26T12:42:25.803Z"},{"id":"019f9e72-b68e-79f7-923d-49cece0f994c","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","prompt":"A number p has exactly 12 factors. Two of its factors are 4 and 15. Find one possible value of p.","model_answer":"60","explanation":"The number must be divisible by both 4 and 15, so it must be a multiple of 60. Now 60 = 2^2 × 3 × 5, so the number of factors is (2+1)(1+1)(1+1) = 12. Therefore one possible value is 60.","difficulty":"Medium","diagram_path":null,"metadata":{"tags":"numbers,factors,prime-factorisation","subtopic":"factors","question_type":"open-ended","diagram_required":false},"question_type":"open-ended","created_at":"2026-07-26T12:42:25.806Z","updated_at":"2026-07-26T12:42:25.806Z"},{"id":"019f9e72-b691-7764-8288-e89f71e5bb84","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","prompt":"Express 840 as a product of prime factors.","model_answer":"2^3 × 3 × 5 × 7","explanation":"840 = 84 × 10 = (2^2 × 3 × 7) × (2 × 5) = 2^3 × 3 × 5 × 7.","difficulty":"Easy","diagram_path":null,"metadata":{"tags":"numbers,prime-factorisation","subtopic":"prime factorisation","question_type":"open-ended","diagram_required":false},"question_type":"open-ended","created_at":"2026-07-26T12:42:25.809Z","updated_at":"2026-07-26T12:42:25.809Z"},{"id":"019f9e72-b69b-7385-b3c7-64e19ae59966","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","prompt":"The least common multiple of 12, x and 28 is 420. Find two possible values of x between 12 and 100.","model_answer":"15 and 35","explanation":"420 = 2^2 × 3 × 5 × 7. Since 12 = 2^2 × 3 and 28 = 2^2 × 7, x must contribute a factor of 5 without creating higher powers that change the LCM. Two possible values are 15 and 35.","difficulty":"Medium","diagram_path":null,"metadata":{"tags":"numbers,lcm,factors","subtopic":"lcm","question_type":"open-ended","diagram_required":false},"question_type":"open-ended","created_at":"2026-07-26T12:42:25.819Z","updated_at":"2026-07-26T12:42:25.819Z"},{"id":"019f9e72-b69e-73de-893e-74388ffc703e","topic_id":"019f9df7-a2a2-7839-8287-1e75e9dd37f8","prompt":"Jessica invests $4540 at a rate of r% per year compound interest. At the end of 10 years, she has earned $1328.54 in interest. Find the value of r.","model_answer":"2.5%","explanation":"Final amount = 4540 + 1328.54 = 5868.54. So 4540(1 + r/100)^10 = 5868.54. Divide by 4540 to get (1 + r/100)^10 = 1.292. Taking the 10th root gives 1 + r/100 ≈ 1.025. Therefore r = 2.5%.","difficulty":"Medium","diagram_path":null,"metadata":{"tags":"percentages,compound-interest,finance","subtopic":"compound interest","question_type":"open-ended","diagram_required":false},"question_type":"open-ended","created_at":"2026-07-26T12:42:25.822Z","updated_at":"2026-07-26T12:42:25.822Z"},{"id":"019f9e72-b6af-777a-893b-e66b9f69cf0e","topic_id":"019f9df7-a2a2-78ab-b1d6-52be9d287151","prompt":"A regular polygon has interior angle to exterior angle ratio 5:4. Explain why this is impossible.","model_answer":"The number of sides is not a whole number.","explanation":"Let the interior angle be 5x and the exterior angle be 4x. Since they add up to 180°, 9x = 180, so x = 20 and the exterior angle is 80°. The number of sides would be 360 ÷ 80 = 4.5, which is not an integer, so such a regular polygon is impossible.","difficulty":"Medium","diagram_path":null,"metadata":{"tags":"angles,polygons,reasoning","subtopic":"polygons","question_type":"open-ended","diagram_required":false},"question_type":"open-ended","created_at":"2026-07-26T12:42:25.839Z","updated_at":"2026-07-26T12:42:25.839Z"},{"id":"01a00459-8bb0-79e6-ade9-c46eddf891d7","topic_id":"019f9df7-a2a2-7888-aef2-fd58477eb864","prompt":"A cumulative frequency graph for 160 students shows the lower quartile at 56 marks and the upper quartile at 72 marks. Find the interquartile range.","model_answer":"16","explanation":"Interquartile range = upper quartile - lower quartile = 72 - 56 = 16.","difficulty":"Easy","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:36:12.464Z","updated_at":"2026-08-15T07:36:12.464Z"},{"id":"01a00459-8bb6-77a0-8cd3-3690d5b4530c","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","prompt":"Write as a single fraction in its simplest form: 3/(x + 2) + 1/(x - 2).","model_answer":"(4x - 4)/(x^2 - 4)","explanation":"The common denominator is (x + 2)(x - 2) = x^2 - 4. The numerator becomes 3(x - 2) + (x + 2) = 4x - 4. So the single fraction is (4x - 4)/(x^2 - 4).","difficulty":"Medium","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:36:12.470Z","updated_at":"2026-08-15T07:36:12.470Z"},{"id":"01a00459-8bc7-7e97-891d-72fad8fdb80e","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","prompt":"Expand and simplify (2x - 5)(x + 4).","model_answer":"2x^2 + 3x - 20","explanation":"Multiply each term: 2x(x + 4) - 5(x + 4) = 2x^2 + 8x - 5x - 20 = 2x^2 + 3x - 20.","difficulty":"Easy","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:36:12.487Z","updated_at":"2026-08-15T07:36:12.487Z"},{"id":"01a00459-8bcc-7c1a-af1d-41720b9197b5","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","prompt":"Factorise completely: 6y^2 - 15y.","model_answer":"3y(2y - 5)","explanation":"Take out the common factor 3y. This gives 6y^2 - 15y = 3y(2y - 5).","difficulty":"Easy","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:36:12.492Z","updated_at":"2026-08-15T07:36:12.492Z"},{"id":"01a00459-8bdc-7410-ba31-9a3cb9aea481","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","prompt":"Factorise completely: x^2 - 9x + 20.","model_answer":"(x - 4)(x - 5)","explanation":"Find two numbers whose product is 20 and sum is -9. They are -4 and -5, so the expression factorises to (x - 4)(x - 5).","difficulty":"Easy","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:36:12.508Z","updated_at":"2026-08-15T07:36:12.508Z"},{"id":"01a00459-8bef-7ab5-a104-7e114d0dc45f","topic_id":"019f9df7-a2a2-7839-8287-1e75e9dd37f8","prompt":"y is directly proportional to the cube root of (x + 1). It is given that x = 7 when y = 1. Find the value of y when x = 124.","model_answer":"2.5","explanation":"Let y = k∛(x + 1). When x = 7, 1 = k∛8 = 2k, so k = 1/2. When x = 124, y = 1/2 × ∛125 = 1/2 × 5 = 2.5.","difficulty":"Medium","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:36:12.527Z","updated_at":"2026-08-15T07:36:12.527Z"},{"id":"01a00459-8c14-7cd2-b241-27a307a25f99","topic_id":"019f9df7-a2a2-7839-8287-1e75e9dd37f8","prompt":"F is inversely proportional to the square of d. Explain what happens to F when d is halved.","model_answer":"F becomes 4 times the original value.","explanation":"Since F is inversely proportional to d^2, halving d makes d^2 become one quarter of the original value. Therefore F becomes 4 times as large.","difficulty":"Easy","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:36:12.564Z","updated_at":"2026-08-15T07:36:12.564Z"},{"id":"01a00459-8c28-7a53-b1de-56308e632bf5","topic_id":"019f9df7-a2a2-7899-9f80-1aed5da88c11","prompt":"In a cake recipe problem, a matrix product AB is used to combine ingredient amounts with the number of cakes baked. Explain what the entries of AB represent.","model_answer":"They represent the total amounts of each ingredient required.","explanation":"When a matrix of ingredient quantities per cake is multiplied by a matrix showing how many cakes are made, each entry in the product gives the total amount of a particular ingredient needed.","difficulty":"Easy","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:36:12.584Z","updated_at":"2026-08-15T07:36:12.584Z"},{"id":"01a00459-8c3c-7f99-a598-2738e3fd3e42","topic_id":"019f9df7-a2a2-7839-8287-1e75e9dd37f8","prompt":"Express 10 000 SGD in USD if the exchange rate is USD 1 = SGD x.","model_answer":"10000/x","explanation":"If 1 USD = x SGD, then the number of USD received for 10 000 SGD is 10 000 divided by x.","difficulty":"Easy","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:36:12.604Z","updated_at":"2026-08-15T07:36:12.604Z"},{"id":"01a00459-8c50-79ba-ad59-2e502c606165","topic_id":"019f9df7-a2a2-7839-8287-1e75e9dd37f8","prompt":"Two exchange rates are given: 1 USD = SGD x in 2023, and in 2022 the rate was SGD 0.030 less per USD. The difference in exchanging SGD 10 000 between the two years is USD 166. Write down the equation in x.","model_answer":"10000/x - 10000/(x - 0.030) = 166","explanation":"In 2023, 10 000 SGD gives 10000/x USD. In 2022, 10 000 SGD gives 10000/(x - 0.030) USD. Their difference is 166 USD, so 10000/x - 10000/(x - 0.030) = 166.","difficulty":"Medium","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:36:12.624Z","updated_at":"2026-08-15T07:36:12.624Z"},{"id":"01a00459-8c78-7f7a-8cd5-4ec7c331a4f1","topic_id":"019f9df7-a2a2-77cc-bb88-40ce254805a8","prompt":"Show that (7n - 1)^2 - (n - 1)^2 is a multiple of 12 for all integer values of n.","model_answer":"12n(4n - 1)","explanation":"Use the difference of two squares: (7n - 1)^2 - (n - 1)^2 = [(7n - 1) + (n - 1)] [(7n - 1) - (n - 1)] = (8n - 2)(6n). This simplifies to 12n(4n - 1), which is always divisible by 12.","difficulty":"Medium","diagram_path":null,"metadata":{"diagram_required":false},"question_type":null,"created_at":"2026-08-15T07:36:12.664Z","updated_at":"2026-08-15T07:36:12.664Z"},{"id":"019f9e72-b6b5-78bc-9d44-95b008df431a","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"Explain why x^2 - 10x + 7 has its minimum value when x = 5.","model_answer":"Because the squared term is smallest when x = 5.","explanation":"From x^2 - 10x + 7 = (x - 5)^2 - 18, the squared term (x - 5)^2 is always at least 0. It is smallest when x = 5, so the whole expression is minimum at x = 5.","difficulty":"Easy","diagram_path":null,"metadata":{"tags":"algebra,quadratics,minimum-value","subtopic":"quadratic expressions","question_type":"open-ended","diagram_required":false},"question_type":"open-ended","created_at":"2026-07-26T12:42:25.845Z","updated_at":"2026-07-26T12:42:25.845Z"},{"id":"019f9e72-b6b8-7861-a416-d5144be184bf","topic_id":"019f9df7-a2a2-7839-8287-1e75e9dd37f8","prompt":"A shopkeeper makes a loss of 24% when selling an item for $136. Find the selling price needed to make a profit of 40%.","model_answer":"$250","explanation":"If $136 is 76% of the cost price, then cost price = 136 ÷ 0.76 = 178.947... For a 40% profit, selling price = 1.4 × 178.947... = 250. So the required selling price is $250.","difficulty":"Medium","diagram_path":null,"metadata":{"tags":"percentages,profit-and-loss,money","subtopic":"profit and loss","question_type":"open-ended","diagram_required":false},"question_type":"open-ended","created_at":"2026-07-26T12:42:25.848Z","updated_at":"2026-07-26T12:42:25.848Z"},{"id":"019f9e72-b6bb-7080-b66e-034f8986efeb","topic_id":"019f9df7-a2a2-77cc-bb88-40ce254805a8","prompt":"A bag contains yellow and blue balls in the ratio 1:4. Five yellow balls are removed and 10 blue balls are added. The new ratio becomes 1:6. Find the original number of yellow balls.","model_answer":"20","explanation":"Let the original numbers be x and 4x. After the change, they become x - 5 and 4x + 10. Given (x - 5)/(4x + 10) = 1/6. So 6x - 30 = 4x + 10, hence 2x = 40 and x = 20.","difficulty":"Medium","diagram_path":null,"metadata":{"tags":"ratio,word-problem,algebra","subtopic":"changing ratios","question_type":"open-ended","diagram_required":false},"question_type":"open-ended","created_at":"2026-07-26T12:42:25.850Z","updated_at":"2026-07-26T12:42:25.850Z"},{"id":"019f9e72-b6c3-7306-91ea-93021d2cea00","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"Each term in a sequence is obtained by subtracting the same number from the previous term. The sequence is 78, a, b, c, 42, ... Find a, b and c.","model_answer":"a = 69, b = 60, c = 51","explanation":"There are 4 equal steps from 78 to 42, so the common difference is (42 - 78) ÷ 4 = -9. Therefore a = 69, b = 60 and c = 51.","difficulty":"Easy","diagram_path":null,"metadata":{"tags":"algebra,sequences,arithmetic-progression","subtopic":"arithmetic sequences","question_type":"open-ended","diagram_required":false},"question_type":"open-ended","created_at":"2026-07-26T12:42:25.859Z","updated_at":"2026-07-26T12:42:25.859Z"},{"id":"019f9e72-b6c5-7f54-b639-d7a7557042e9","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"Write an expression in terms of n for the nth term of the sequence 78, 69, 60, 51, ...","model_answer":"87 - 9n","explanation":"The first term is 78 and the common difference is -9. So the nth term is 78 + (n - 1)(-9) = 87 - 9n.","difficulty":"Easy","diagram_path":null,"metadata":{"tags":"algebra,sequences,nth-term","subtopic":"nth term","question_type":"open-ended","diagram_required":false},"question_type":"open-ended","created_at":"2026-07-26T12:42:25.861Z","updated_at":"2026-07-26T12:42:25.861Z"},{"id":"019f9e72-b6ca-7903-9322-9edf29f8572c","topic_id":"019f9df7-a2a2-7888-aef2-fd58477eb864","prompt":"The universal set contains the integers from 1 to 15. Set A contains the perfect squares and set B contains the prime numbers. Find n(A ∪ B).","model_answer":"9","explanation":"A = {1, 4, 9}. B = {2, 3, 5, 7, 11, 13}. There is no overlap, so n(A ∪ B) = 3 + 6 = 9.","difficulty":"Easy","diagram_path":null,"metadata":{"tags":"sets,union,number-of-elements","subtopic":"set operations","question_type":"open-ended","diagram_required":false},"question_type":"open-ended","created_at":"2026-07-26T12:42:25.866Z","updated_at":"2026-07-26T12:42:25.866Z"},{"id":"019f9e72-b6cd-76b7-8761-7b183729226c","topic_id":"019f9df7-a2a2-7888-aef2-fd58477eb864","prompt":"The universal set contains the integers from 1 to 15. Set B contains the prime numbers. List the elements of B'.","model_answer":"{1, 4, 6, 8, 9, 10, 12, 14, 15}","explanation":"The primes from 1 to 15 are 2, 3, 5, 7, 11 and 13. The complement B' contains all other integers in the universal set.","difficulty":"Easy","diagram_path":null,"metadata":{"tags":"sets,complement,prime-numbers","subtopic":"complement of a set","question_type":"open-ended","diagram_required":false},"question_type":"open-ended","created_at":"2026-07-26T12:42:25.869Z","updated_at":"2026-07-26T12:42:25.869Z"},{"id":"019f9e72-b6cf-7a9b-9f18-e58a5e6ec9c6","topic_id":"019f9df7-a2a2-7930-a717-cd252273c91f","prompt":"A cumulative frequency graph for 160 students shows the lower quartile at 56 marks and the upper quartile at 72 marks. Find the interquartile range.","model_answer":"16","explanation":"Interquartile range = upper quartile - lower quartile = 72 - 56 = 16.","difficulty":"Easy","diagram_path":null,"metadata":{"tags":"data,statistics,cumulative-frequency","subtopic":"interquartile range","question_type":"open-ended","diagram_required":false},"question_type":"open-ended","created_at":"2026-07-26T12:42:25.871Z","updated_at":"2026-07-26T12:42:25.871Z"},{"id":"019f9e72-b6d7-71fb-a11b-81d02558f9ed","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"Write as a single fraction in its simplest form: 3/(x + 2) + 1/(x - 2).","model_answer":"(4x - 4)/(x^2 - 4)","explanation":"The common denominator is (x + 2)(x - 2) = x^2 - 4. The numerator becomes 3(x - 2) + (x + 2) = 4x - 4. So the single fraction is (4x - 4)/(x^2 - 4).","difficulty":"Medium","diagram_path":null,"metadata":{"tags":"algebra,fractions,simplification","subtopic":"algebraic fractions","question_type":"open-ended","diagram_required":false},"question_type":"open-ended","created_at":"2026-07-26T12:42:25.879Z","updated_at":"2026-07-26T12:42:25.879Z"},{"id":"019f9e72-b6d9-7ffe-bda0-9c483c9a0e0b","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"Expand and simplify (2x - 5)(x + 4).","model_answer":"2x^2 + 3x - 20","explanation":"Multiply each term: 2x(x + 4) - 5(x + 4) = 2x^2 + 8x - 5x - 20 = 2x^2 + 3x - 20.","difficulty":"Easy","diagram_path":null,"metadata":{"tags":"algebra,expansion,brackets","subtopic":"expansion","question_type":"open-ended","diagram_required":false},"question_type":"open-ended","created_at":"2026-07-26T12:42:25.881Z","updated_at":"2026-07-26T12:42:25.881Z"},{"id":"019f9e72-b6dc-7545-99f7-60cd11ca51f2","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"Factorise completely: 6y^2 - 15y.","model_answer":"3y(2y - 5)","explanation":"Take out the common factor 3y. This gives 6y^2 - 15y = 3y(2y - 5).","difficulty":"Easy","diagram_path":null,"metadata":{"tags":"algebra,factorisation,common-factor","subtopic":"factorisation","question_type":"open-ended","diagram_required":false},"question_type":"open-ended","created_at":"2026-07-26T12:42:25.884Z","updated_at":"2026-07-26T12:42:25.884Z"},{"id":"019f9e72-b6de-78c6-bd8c-d34069e07a12","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"Factorise completely: x^2 - 9x + 20.","model_answer":"(x - 4)(x - 5)","explanation":"Find two numbers whose product is 20 and sum is -9. They are -4 and -5, so the expression factorises to (x - 4)(x - 5).","difficulty":"Easy","diagram_path":null,"metadata":{"tags":"algebra,factorisation,quadratics","subtopic":"quadratic factorisation","question_type":"open-ended","diagram_required":false},"question_type":"open-ended","created_at":"2026-07-26T12:42:25.886Z","updated_at":"2026-07-26T12:42:25.886Z"},{"id":"019f9e72-b6e0-7e2c-84ee-9587e00dc897","topic_id":"019f9df7-a2a2-77cc-bb88-40ce254805a8","prompt":"y is directly proportional to the cube root of (x + 1). It is given that x = 7 when y = 1. Find the value of y when x = 124.","model_answer":"2.5","explanation":"Let y = k∛(x + 1). When x = 7, 1 = k∛8 = 2k, so k = 1/2. When x = 124, y = 1/2 × ∛125 = 1/2 × 5 = 2.5.","difficulty":"Medium","diagram_path":null,"metadata":{"tags":"ratio,direct-proportion,cube-root","subtopic":"direct proportion","question_type":"open-ended","diagram_required":false},"question_type":"open-ended","created_at":"2026-07-26T12:42:25.888Z","updated_at":"2026-07-26T12:42:25.888Z"},{"id":"019f9e72-b6e3-75ef-8fce-32f0a433dfb3","topic_id":"019f9df7-a2a2-77cc-bb88-40ce254805a8","prompt":"F is inversely proportional to the square of d. Explain what happens to F when d is halved.","model_answer":"F becomes 4 times the original value.","explanation":"Since F is inversely proportional to d^2, halving d makes d^2 become one quarter of the original value. Therefore F becomes 4 times as large.","difficulty":"Easy","diagram_path":null,"metadata":{"tags":"ratio,inverse-proportion,variation","subtopic":"inverse proportion","question_type":"open-ended","diagram_required":false},"question_type":"open-ended","created_at":"2026-07-26T12:42:25.891Z","updated_at":"2026-07-26T12:42:25.891Z"},{"id":"019f9e72-b6ea-7f6c-bea0-df74736325f2","topic_id":"019f9df7-a2a2-7899-9f80-1aed5da88c11","prompt":"In a cake recipe problem, a matrix product AB is used to combine ingredient amounts with the number of cakes baked. Explain what the entries of AB represent.","model_answer":"They represent the total amounts of each ingredient required.","explanation":"When a matrix of ingredient quantities per cake is multiplied by a matrix showing how many cakes are made, each entry in the product gives the total amount of a particular ingredient needed.","difficulty":"Easy","diagram_path":null,"metadata":{"tags":"matrices,application,interpretation","subtopic":"matrix interpretation","question_type":"open-ended","diagram_required":false},"question_type":"open-ended","created_at":"2026-07-26T12:42:25.898Z","updated_at":"2026-07-26T12:42:25.898Z"},{"id":"019f9ebf-c0c8-72d8-b93d-670b5793463d","topic_id":"019f9df7-a2a2-77cc-bb88-40ce254805a8","prompt":"Express 10 000 SGD in USD if the exchange rate is USD 1 = SGD x.","model_answer":"10000/x","explanation":"If 1 USD = x SGD, then the number of USD received for 10 000 SGD is 10 000 divided by x.","difficulty":"Easy","diagram_path":null,"metadata":{"tags":"ratio,exchange-rates,money","subtopic":"exchange rates","question_type":"open-ended","diagram_required":false},"question_type":"open-ended","created_at":"2026-07-26T14:06:34.695Z","updated_at":"2026-07-26T14:06:34.695Z"},{"id":"019f9ebf-c0d2-7459-98ef-aad8dc14a00a","topic_id":"019f9df7-a2a2-77cc-bb88-40ce254805a8","prompt":"Two exchange rates are given: 1 USD = SGD x in 2023, and in 2022 the rate was SGD 0.030 less per USD. The difference in exchanging SGD 10 000 between the two years is USD 166. Write down the equation in x.","model_answer":"10000/x - 10000/(x - 0.030) = 166","explanation":"In 2023, 10 000 SGD gives 10000/x USD. In 2022, 10 000 SGD gives 10000/(x - 0.030) USD. Their difference is 166 USD, so 10000/x - 10000/(x - 0.030) = 166.","difficulty":"Medium","diagram_path":null,"metadata":{"tags":"ratio,exchange-rates,algebra","subtopic":"exchange rates","question_type":"open-ended","diagram_required":false},"question_type":"open-ended","created_at":"2026-07-26T14:06:34.706Z","updated_at":"2026-07-26T14:06:34.706Z"},{"id":"019f9ebf-c0da-7813-b431-055592fa6664","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","prompt":"Show that (7n - 1)^2 - (n - 1)^2 is a multiple of 12 for all integer values of n.","model_answer":"12n(4n - 1)","explanation":"Use the difference of two squares: (7n - 1)^2 - (n - 1)^2 = [(7n - 1) + (n - 1)] [(7n - 1) - (n - 1)] = (8n - 2)(6n). This simplifies to 12n(4n - 1), which is always divisible by 12.","difficulty":"Medium","diagram_path":null,"metadata":{"tags":"numbers,proof,algebra","subtopic":"multiple of 12","question_type":"open-ended","diagram_required":false},"question_type":"open-ended","created_at":"2026-07-26T14:06:34.714Z","updated_at":"2026-07-26T14:06:34.714Z"},{"id":"019f9ebf-c0de-7550-b119-103e3c4ba23a","topic_id":"019f9df7-a2a2-7853-96ff-2c02dc5e1f10","prompt":"Simplify (p - 3n)(4n - 1) / [12n(4n - 1)].","model_answer":"(3n - p)/(12n)","explanation":"Cancel the common factor (4n - 1) from numerator and denominator. Since p - 3n = -(3n - p), the expression becomes (3n - p)/(12n).","difficulty":"Medium","diagram_path":null,"metadata":{"tags":"algebra,fractions,simplification","subtopic":"algebraic fractions","question_type":"open-ended","diagram_required":false},"question_type":"open-ended","created_at":"2026-07-26T14:06:34.718Z","updated_at":"2026-07-26T14:06:34.718Z"},{"id":"019f9ebf-c0e1-7e17-b0f4-c94a7c857d61","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","prompt":"The green and red lights flash every 6 seconds and 8 seconds respectively. If they start together, how long will it take for them to next flash simultaneously?","model_answer":"24 s","explanation":"Find the least common multiple of 6 and 8. LCM(6, 8) = 24, so they will next flash together after 24 seconds.","difficulty":"Easy","diagram_path":null,"metadata":{"tags":"numbers,lcm,time","subtopic":"lcm","question_type":"open-ended","diagram_required":false},"question_type":"open-ended","created_at":"2026-07-26T14:06:34.721Z","updated_at":"2026-07-26T14:06:34.721Z"},{"id":"019f9ebf-c0e5-7b31-b834-96bab2ec6168","topic_id":"019f9df7-a2a0-71cf-9863-4d6d67e42e6d","prompt":"Express 2250 as a product of its prime factors.","model_answer":"2 × 3^2 × 5^3","explanation":"2250 = 225 × 10 = (3^2 × 5^2) × (2 × 5) = 2 × 3^2 × 5^3.","difficulty":"Easy","diagram_path":null,"metadata":{"tags":"numbers,prime-factorisation","subtopic":"prime factorisation","question_type":"open-ended","diagram_required":false},"question_type":"open-ended","created_at":"2026-07-26T14:06:34.725Z","updated_at":"2026-07-26T14:06:34.725Z"},{"id":"019f9ebf-c0e9-779f-87dc-0cfb78d5ac8a","topic_id":"019f9df7-a2a2-77cc-bb88-40ce254805a8","prompt":"The period P of a pendulum is directly proportional to the square root of its length L. If P increases by 25%, what is the percentage increase in L?","model_answer":"56.25%","explanation":"Since P is proportional to sqrt(L), L is proportional to P^2. If P increases by 25%, then L changes by 1.25^2 = 1.5625. So the increase in L is 56.25%.","difficulty":"Medium","diagram_path":null,"metadata":{"tags":"ratio,proportion,percentage-change","subtopic":"direct proportion","question_type":"open-ended","diagram_required":false},"question_type":"open-ended","created_at":"2026-07-26T14:06:34.729Z","updated_at":"2026-07-26T14:06:34.729Z"},{"id":"019f9ebf-c0ed-76a8-b98d-3f0ba732ac5c","topic_id":"019f9df7-a2a2-78fc-bd9e-a40e9b4f9363","prompt":"The Great Pyramid has surface area 8.30 × 10^4 m^2 and volume 2.45 × 10^4 m^3. A similar replica has volume 9.22 × 10^-6 m^3. Estimate the surface area of the replica.","model_answer":"4.33 × 10^-2 m^2","explanation":"For similar solids, surface area scales with the square of the linear scale and volume scales with the cube. Use the volume ratio to find the linear scale, then square it and apply it to 8.30 × 10^4. This gives approximately 4.33 × 10^-2 m^2.","difficulty":"Hard","diagram_path":null,"metadata":{"tags":"mensuration,similar-shapes,scaling","subtopic":"similar solids","question_type":"open-ended","diagram_required":false},"question_type":"open-ended","created_at":"2026-07-26T14:06:34.733Z","updated_at":"2026-07-26T14:06:34.733Z"},{"id":"019f9ebf-c0f1-7eb2-8663-cafb16ce1472","topic_id":"019f9df7-a2a2-7888-aef2-fd58477eb864","prompt":"The universal set is the integers from 0 to 10. Set A = {1, 4, 9} and set B = {1, 2, 4, 8}. Describe the elements of set A.","model_answer":"Perfect squares","explanation":"The elements 1, 4 and 9 are the perfect squares in the universal set from 0 to 10.","difficulty":"Easy","diagram_path":null,"metadata":{"tags":"sets,perfect-squares","subtopic":"set description","question_type":"open-ended","diagram_required":false},"question_type":"open-ended","created_at":"2026-07-26T14:06:34.737Z","updated_at":"2026-07-26T14:06:34.737Z"},{"id":"019f9ebf-c0f5-75c8-9b42-505c50871466","topic_id":"019f9df7-a2a2-7888-aef2-fd58477eb864","prompt":"Find the number of elements in A ∪ B, where A = {1, 4, 9} and B = {1, 2, 4, 8}.","model_answer":"5","explanation":"A ∪ B = {1, 2, 4, 8, 9}. There are 5 elements in the union.","difficulty":"Easy","diagram_path":null,"metadata":{"tags":"sets,union,number-of-elements","subtopic":"union of sets","question_type":"open-ended","diagram_required":false},"question_type":"open-ended","created_at":"2026-07-26T14:06:34.741Z","updated_at":"2026-07-26T14:06:34.741Z"}]$seed$)
